@Service
public class StreamImportService {

    private final TransactionTemplate transactionTemplate;
    private final JdbcTemplate jdbcTemplate;

    public StreamImportService(PlatformTransactionManager transactionManager, JdbcTemplate jdbcTemplate) {
        this.transactionTemplate = new TransactionTemplate(transactionManager);
        this.transactionTemplate.setIsolationLevel(TransactionDefinition.ISOLATION_READ_COMMITTED);
        this.transactionTemplate.setPropagationBehavior(TransactionDefinition.PROPAGATION_REQUIRED);
        this.jdbcTemplate = jdbcTemplate;
    }

    public void processDataStream(ReadableByteChannel channel) {
        transactionTemplate.execute(status -> {
            try {
                ByteBuffer buffer = ByteBuffer.allocate(1024);
                while (channel.read(buffer) != -1) {
                    buffer.flip();
                    // Perform batch I/O and database operations
                    jdbcTemplate.update("INSERT INTO staging_data (payload) VALUES (?)", buffer.toString());
                    buffer.clear();
                }
            } catch (IOException e) {
                // Mark rollback explicitly upon I/O failure
                status.setRollbackOnly();
                throw new UncheckedIOException(e);
            }
            return null;
        });
    }
}
